const img=(s,alt,cls='',lazy=true)=>{const meta=IMAGE_ASSETS[s],variants=meta?.variants;return `<img src="${asset(variants?variants.at(-1)[0]:s)}" alt="${esc(alt)}" class="${cls}" ${meta?`width="${meta.w}" height="${meta.h}"`:''} ${variants?`srcset="${variants.map(([file,w])=>asset(file)+' '+w+'w').join(', ')}" sizes="(max-width:760px) 100vw, 1280px"`:''} ${lazy?'loading="lazy"':'loading="eager"'} decoding="async">`;};
const categories=()=>[...new Set(state.products.map(p=>p.category))];
const published=()=>state.products.filter(p=>p.status==='Publicado');
const btn=(label,href,cls='')=>`<a class="btn ${cls}" href="${href}">${label}</a>`;
const route=()=>decodeURIComponent(location.hash.slice(1)||'/');
const save=()=>{try{localStorage.setItem('foodtex-demo-v1',JSON.stringify(state));return true}catch{toast('No se pudo guardar: el almacenamiento del navegador está lleno.');return false}};
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),3500)}
function header(){const r=route();return `<div class="topbar"><div class="wrap"><span>Soluciones para la industria frigorífica</span><span>Concepción del Uruguay, Argentina · <a href="mailto:${esc(state.settings.email)}">${esc(state.settings.email)}</a></span></div></div><header class="header"><div class="wrap nav"><a href="#/" aria-label="FOODTEX, inicio">${img('logo-foodtex-2026-c.png','FOODTEX · Reliable Solutions','logo',false)}</a><button class="menu" data-action="menu" aria-label="Abrir navegación" aria-expanded="false" aria-controls="primary-navigation">☰</button><nav id="primary-navigation" class="navlinks" aria-label="Navegación principal">${[['Inicio','/'],['Productos','/productos'],['Nosotros','/nosotros'],['Novedades','/novedades'],['Contacto','/contacto']].map(([t,l])=>`<a href="#${l}" class="${r===l?'active':''}">${t}</a>`).join('')}<a class="mobile-quote-link" href="#/cotizacion">Solicitar cotización</a></nav><a class="btn" href="#/cotizacion">Solicitar cotización ${quote.length?`<span class="quote-count">${quote.length}</span>`:''}</a></div></header>`}
function footer(){return `${route()==='/'?'':`<section class="cta"><div class="wrap"><div><h2>Una solución para tu próximo desafío.</h2><p>Contanos qué necesita tu planta. Te ayudamos a elegir.</p></div>${btn('Hablemos de tu proyecto','#/contacto','light')}</div></section>`}<footer class="footer"><div class="wrap"><div class="footer-grid"><div><a href="#/">${img('logo-foodtex-2026-c.png','FOODTEX','logo')}</a><p>Insumos, equipos y soporte técnico<br>para la industria frigorífica.</p></div><div><h4>Explorá FOODTEX</h4><div class="footer-links"><a href="#/productos">Productos</a><a href="#/nosotros">Nosotros</a><a href="#/novedades">Novedades</a><a href="#/contacto">Contacto</a></div></div><div><h4>Encontranos</h4><p>${esc(state.settings.address)}</p><a href="https://www.google.com/maps/search/?api=1&query=Foodtex+Concepci%C3%B3n+del+Uruguay" target="_blank" rel="noopener">Ver ubicación en Google Maps</a></div><div><h4>Contacto</h4><div class="footer-links"><a href="mailto:${esc(state.settings.email)}">${esc(state.settings.email)}</a><a href="tel:+${digits(state.settings.phone)}">${esc(state.settings.phone)}</a><span style="font-size:13px;color:#b4c5d9">Atención: ${esc(state.settings.hours)}</span></div></div></div><div class="footer-wordmark" aria-hidden="true">FOODTEX<span>®</span></div><div class="foot-bottom"><span>© ${new Date().getFullYear()} FOODTEX · Reliable Solutions</span><a href="#/admin">Administración · Demo</a></div></div></footer>`}
const digits=s=>s.replace(/\D/g,'');
function brands(){return `<div class="brands"><div class="wrap brand-row"><span>TECNOLOGÍA GLOBAL.<br>RESPALDO LOCAL.</span>${BRANDS.map(([name,file])=>img(file,name)).join('')}</div></div>`}
function productCard(p){return `<article class="product-card ${p.featured?'product-featured':''}"><a href="#/producto/${p.id}"><div class="product-img"><span class="tag">${esc(p.brand)}</span>${img(p.image,p.name)}</div></a><div class="product-body"><div class="meta">${esc(p.category)}</div><h3><a href="#/producto/${p.id}">${esc(p.name)}</a></h3><p>${esc(p.summary)}</p><div class="product-bottom"><a class="textlink" href="#/producto/${p.id}">Ver producto</a><button class="plus" data-action="add-quote" data-id="${p.id}" aria-label="Agregar ${esc(p.name)} a cotización">${quote.includes(p.id)?'✓':'+'}</button></div></div></article>`}
function newsCard(n){return `<article class="news-card"><a href="#/novedad/${n.id}">${img(n.image,n.title)}<div class="meta">${esc(n.category).toUpperCase()}</div><h3>${esc(n.title)}</h3></a><p>${esc(n.summary)}</p><a class="textlink" href="#/novedad/${n.id}">Leer novedad</a></article>`}
function home(){return `<main class="premium-home machine-experience"><div class="scroll-progress" aria-hidden="true"></div><section class="premium-hero cinematic-hero"><div class="cinematic-background" data-parallax="0.035"><img src="assets/conveyor-concept-v4.webp" alt="Composición conceptual de tecnología industrial en acero inoxidable" fetchpriority="high"></div><div class="cinematic-shade"></div><div class="hero-orbit" aria-hidden="true"><span>PRECISIÓN / MOVIMIENTO</span></div><div class="wrap premium-hero-grid"><div class="premium-hero-copy"><span class="eyebrow intro-in">FOODTEX · RELIABLE SOLUTIONS</span><h1 class="intro-in">${esc(state.settings.title).replace('tu industria.','<span>tu industria.</span>')}</h1><p class="intro-in">${esc(state.settings.subtitle.split('.')[0]+'.')}</p><div class="actions intro-in">${btn('Descubrir soluciones','#/productos','light')}</div><a class="scroll-cue" href="#recorrido" data-action="scroll-tour"><span class="scroll-line"></span>DESLIZÁ PARA DESCUBRIR</a></div></div><div class="machine-baseline wrap"><span class="machine-status"><i></i> SOLUCIONES EN MOVIMIENTO</span><div class="hero-words" aria-label="Asesoramiento, instalación y soporte"><span aria-hidden="true">ASESORAMIENTO<br>INSTALACIÓN<br>SOPORTE<br>ASESORAMIENTO</span></div><span>FOODTEX / INDUSTRIA FRIGORÍFICA</span></div></section><section class="brand-marquee"><div class="wrap"><span class="eyebrow">TECNOLOGÍA GLOBAL. RESPALDO LOCAL.</span></div><div class="marquee-window"><div class="marquee-track">${[0,1].map((_,i)=>`<div class="marquee-group" ${i?'aria-hidden="true"':''}>${BRANDS.map(([name,file])=>img(file,name)).join('')}</div>`).join('')}</div></div></section><section class="manifesto section" id="recorrido"><div class="wrap"><div class="chapter-label" aria-hidden="true"><span>01 / CONECTAMOS</span><span class="technical-cross">+</span></div><span class="eyebrow" data-reveal>EL VALOR DE ELEGIR BIEN</span><h2 class="manifesto-text word-scroll" data-reveal>Una industria en movimiento. <br><span>Un aliado en cada proceso.</span></h2><div class="manifesto-bottom"><p data-reveal>Detrás de cada línea de producción hay decisiones que importan. Acercamos tecnología y conocimiento para ayudarte a tomar la correcta.</p><a class="round-link" href="#/nosotros" data-reveal>Conocé<br>FOODTEX <span>↗</span></a></div></div></section>${solutionExplorer()}${carnaveCase()}${serviceExperience()}${institutionalScene()}${journalHome()}<section class="statement-section"><div class="statement-drawing" aria-hidden="true"></div><div class="wrap"><span class="eyebrow" data-reveal>EL PRÓXIMO PASO ES TUYO</span><h2 data-reveal>Hagamos que<br><span>las cosas pasen.</span></h2><div class="statement-bottom" data-reveal><p>Contanos tu próximo desafío.<br>Encontramos la solución, juntos.</p>${btn('Iniciar una conversación <span aria-hidden="true">↗</span>','#/contacto','light')}</div></div></section></main>`}
function solutionSelection(){const all=published();return [...new Set(all.map(p=>p.category))].map(c=>all.find(p=>p.category===c&&p.featured)||all.find(p=>p.category===c));}
function solutionExplorer(){const items=solutionSelection();if(!items.length)return '';return `<section class="solutions-explorer section" aria-labelledby="explorer-heading"><div class="wrap"><div class="explorer-layout"><div class="explorer-index"><span class="eyebrow">SOLUCIONES FOODTEX</span><h2 id="explorer-heading">Explorá nuestras<br>soluciones.</h2><p>Elegí un proceso. Encontrá un componente para tu planta.</p><div class="explorer-tabs" role="tablist" aria-label="Procesos industriales">${items.map((p,i)=>`<button id="solution-tab-${i}" role="tab" aria-selected="${i===0}" aria-controls="solution-view-${i}" tabindex="${i===0?0:-1}" data-explore="${i}"><span>${String(i+1).padStart(2,'0')}</span><strong>${esc(p.category)}</strong><i aria-hidden="true"></i></button>`).join('')}</div><a class="explorer-catalog textlink" href="assets/Catalogo-General-Foodtex-2026_compressed.pdf" target="_blank" rel="noopener">VER CATÁLOGO COMPLETO <span aria-hidden="true">↗</span></a></div><div class="explorer-stage" aria-label="Selección de soluciones">${items.map((p,i)=>`<article class="explorer-card ${i===0?'active':''}" id="solution-view-${i}" role="tabpanel" aria-labelledby="solution-tab-${i}" data-explorer-card="${i}"><div class="explorer-media"><span class="explorer-big-number" aria-hidden="true">${String(i+1).padStart(2,'0')}</span>${img(p.image,p.name)}<span class="explorer-brand">${esc(p.brand)}</span></div><div class="explorer-copy"><span class="eyebrow">${esc(p.category)}</span><h3>${esc(p.name)}</h3><p>${esc(p.summary)}</p><div class="explorer-actions"><a class="textlink" href="#/producto/${p.id}">Conocer la solución <span aria-hidden="true">↗</span></a><button class="explorer-quote" data-action="add-quote" data-id="${p.id}">${quote.includes(p.id)?'Agregado a cotización':'Agregar a cotización'}</button></div></div></article>`).join('')}<span class="explorer-drag-hint" aria-hidden="true">ARRASTRAR</span></div></div><div class="explorer-progress" aria-hidden="true"><span><b>01</b> / ${String(items.length).padStart(2,'0')}</span><div><i></i></div><small>DESLIZÁ PARA EXPLORAR</small></div><a class="explorer-mobile-catalog textlink" href="assets/Catalogo-General-Foodtex-2026_compressed.pdf" target="_blank" rel="noopener">VER CATÁLOGO COMPLETO <span aria-hidden="true">↗</span></a></div></section>`;}
function carnaveCase(){return `<section class="carnave-case"><div class="wrap"><div class="carnave-heading"><div><span class="eyebrow" data-reveal>DEL COMPONENTE A LA OPERACIÓN</span><h2 data-reveal>La tecnología cobra valor<br>cuando funciona<br><em>en tu planta.</em></h2></div><p data-reveal>Instalación y puesta en marcha.<br>FOODTEX junto a Granjas Carnave S.A.</p></div><a class="carnave-film" href="#/novedad/marelec" aria-label="Ver caso Granjas Carnave y video completo"><div class="carnave-film-context"><span>EN PLANTA / ENTRE RÍOS</span><strong>Una solución.<br>En movimiento.</strong><small>BALANZA COMPACTA MARELEC<br>GRANJAS CARNAVE S.A.</small></div><div class="carnave-film-media"><img src="assets/carnave-poster.webp" alt="Balanza compacta Marelec funcionando en Granjas Carnave" loading="lazy"><video muted loop playsinline preload="none" poster="assets/carnave-poster.webp" aria-hidden="true" tabindex="-1"></video></div><div class="carnave-film-bottom"><span>REGISTRO REAL FOODTEX</span><span class="carnave-film-control">VER CASO Y VIDEO <i aria-hidden="true">↗</i></span></div></a><div class="carnave-facts"><div><span>01 / SOLUCIÓN</span><strong>Balanza compacta MARELEC</strong></div><div><span>02 / IMPLEMENTACIÓN</span><strong>Instalación y puesta en marcha</strong></div><div><span>03 / EN PLANTA</span><strong>Granjas Carnave S.A.</strong></div></div></div></section>`;}
function serviceExperience(){const steps=[['Asesoramiento técnico','Elegí con respaldo técnico.','Trabajamos junto a vos para identificar los insumos y equipos que mejor se adaptan a tu proceso.','1647018212387.jpg','FOODTEX en el encuentro técnico de INTA'],['Instalación y puesta en marcha','De la solución a la planta.','Acompañamos la instalación para asegurar el funcionamiento de cada equipo.','plant.jpg','Instalación Marelec en Granjas Carnave S.A.'],['Soporte especializado','Un equipo cerca de vos.','Atención personalizada y soporte técnico para acompañar las necesidades de tu industria.','foodtex-presente-expo-avicola-2023-1.jpeg','FOODTEX en Expo Avícola 2023']];return `<section class="service-machine section"><div class="wrap"><div class="chapter-label" aria-hidden="true"><span>03 / ACOMPAÑAMOS</span><span class="technical-cross">+</span></div><div class="section-head"><div><span class="eyebrow">MÁS QUE UN PROVEEDOR</span><h2>Acompañamos<br>tu operación.</h2></div><p>Una solución confiable necesita más que un buen producto. Necesita un equipo que acompañe.</p></div><div class="service-machine-grid"><aside class="service-display"><div class="service-display-images">${steps.map((x,i)=>`<figure class="service-display-frame ${i===0?'active':''}" data-service-frame="${i}" aria-hidden="${i!==0}">${img(x[3],x[4])}<figcaption>${x[4]}</figcaption></figure>`).join('')}<span class="service-display-number" aria-hidden="true">01</span></div><div class="service-display-caption"><span>NECESIDAD → SOLUCIÓN → RESPALDO</span><span>FOODTEX</span></div></aside><div class="service-steps"><span class="service-process-line" aria-hidden="true"><i class="service-line-fill"></i></span>${steps.map((x,i)=>`<article class="service-step ${i===0?'active':''}" data-service-step="${i}"><span class="service-dot" aria-hidden="true"></span><button class="service-select" aria-pressed="${i===0}"><span>${String(i+1).padStart(2,'0')}</span><span><small>${x[0]}</small><strong>${x[1]}</strong></span><i aria-hidden="true">↗</i></button>${img(x[3],x[4],'service-mobile-image')}<p>${x[2]}</p></article>`).join('')}<a class="textlink service-contact" href="#/contacto">Hablemos de tu necesidad <span aria-hidden="true">→</span></a></div></div></div></section>`}
function pageHero(title,description,label=''){return `<section class="page-hero"><div class="wrap"><div class="breadcrumb"><a href="#/">Inicio</a> / ${esc(label||title)}</div><span class="eyebrow">FOODTEX / ${esc(label||title)}</span><h1>${esc(title)}</h1>${description?`<p>${esc(description)}</p>`:''}</div></section>`}
function catalogue(){return `<main class="catalog-page final-catalog">${pageHero('Soluciones para tu proceso.','Insumos y equipos de marcas líderes. Encontrá el componente que necesita tu planta.','Productos')}<section class="section"><div class="wrap catalog-layout"><aside class="filters"><h2 class="filter-heading">Explorá por proceso</h2><div class="category-options" aria-label="Categorías de productos">${['Todos',...categories()].map(c=>`<button class="filter-btn ${category===c?'selected':''}" aria-pressed="${category===c}" data-action="filter" data-category="${esc(c)}">${esc(c)}<span>${published().filter(p=>c==='Todos'||p.category===c).length}</span></button>`).join('')}</div><div class="catalog-docs"><a href="assets/Catalogo-General-Foodtex-2026_compressed.pdf" target="_blank" rel="noopener">Catálogo general · PDF <span aria-hidden="true">↗</span></a><a href="assets/Catalogo-Dedos-2026-Foodtex_compressed.pdf" target="_blank" rel="noopener">Dedos peladores · PDF <span aria-hidden="true">↗</span></a></div></aside><div><div class="searchbar"><input id="product-search" type="search" aria-label="Buscar productos" placeholder="Buscar producto, marca o aplicación..." value="${esc(query)}"><span id="result-count" class="results" role="status" aria-live="polite"></span></div><div class="grid catalog-grid" id="product-results"></div></div></div></section></main>`}
function filterProducts(){const list=published().filter(p=>(category==='Todos'||p.category===category)&&(p.name+' '+p.brand+' '+p.description).toLocaleLowerCase().includes(query.toLocaleLowerCase()));document.querySelector('#product-results').innerHTML=list.length?list.map(productCard).join(''):'<div class="empty full"><h3>No encontramos productos</h3><p>Probá con otra palabra o elegí otra categoría.</p><button class="btn outline" data-action="clear-filters">Limpiar búsqueda</button></div>';document.querySelector('#result-count').textContent=`${list.length} productos`}
function productDetail(id){const p=published().find(p=>p.id===id);if(!p)return notFound();const related=published().filter(x=>x.id!==p.id&&x.category===p.category).slice(0,3);return `<main class="product-page"><section class="product-intro section"><div class="wrap"><div class="breadcrumb"><a href="#/productos">Productos</a> / ${esc(p.category)}</div><div class="detail-layout"><div class="detail-copy"><span class="eyebrow">${esc(p.brand)} / ${esc(p.category)}</span><h1>${esc(p.name)}</h1><p class="product-lead">${esc(p.summary)}</p><div class="actions"><button class="btn" data-action="request-quote" data-id="${p.id}">Solicitar cotización</button>${btn('Consultar con un asesor','#/contacto','outline')}</div><p class="availability-note">Disponibilidad, compatibilidad y precios a confirmar con nuestro equipo.</p></div><div class="detail-photo">${img(p.image,p.name,'',false)}<span>${esc(p.brand)}</span></div></div></div></section><section class="product-technical section"><div class="wrap"><div class="technical-intro"><span class="eyebrow">EL COMPONENTE EN TU PROCESO</span><h2>Conocé los detalles.</h2><p>${esc(p.description)}</p></div><div class="technical-grid"><div><h3>Características</h3><div class="feature-statements">${p.features.map((t,i)=>`<p><span>${String(i+1).padStart(2,'0')}</span>${esc(t)}</p>`).join('')}</div></div><div><h3>Especificaciones</h3><dl class="specs">${Object.entries(p.specs).map(([k,v])=>`<div class="spec"><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><a class="textlink" href="assets/Catalogo-General-Foodtex-2026_compressed.pdf" target="_blank" rel="noopener">Consultar catálogo general <span aria-hidden="true">↗</span></a></div></div></div></section>${related.length?`<section class="related-products section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">PARA EL MISMO PROCESO</span><h2>Soluciones relacionadas.</h2></div>${btn('Explorar productos','#/productos','outline')}</div><div class="grid">${related.map(productCard).join('')}</div></div></section>`:''}</main>`}
function about(){const chapters=[{label:'Quiénes somos',title:'Cerca de tu industria.',text:state.settings.about,image:'foodtex-presente-expo-avicola-2023-1.jpeg',caption:'FOODTEX · Conexiones con la industria',note:'Desde Concepción del Uruguay, Entre Ríos, acompañamos las necesidades de cada planta.'},{label:'Nuestro respaldo',title:'El mundo, conectado a tu planta.',text:'Trabajamos con marcas líderes para acercar insumos, equipos y tecnología a la industria frigorífica. Combinamos ese respaldo con asesoramiento e instalación especializada.',image:'dump-foodtex4-400x250.jpeg',caption:'Visita de Duram · Vínculos que nos acercan',note:'DURAM · DUPPS · BNL · THIELE · MEITECH'},{label:'Nuestra misión',title:'Avanzar, juntos.',text:state.settings.mission,image:'plant.jpg',caption:'Puesta en marcha Marelec · Granjas Carnave S.A.',note:'Asesoramiento. Instalación. Soporte técnico.'},{label:'Nuestra visión',title:'Lo que viene también nos mueve.',text:state.settings.vision,image:'1647018212387.jpg',caption:'FOODTEX · Encuentro técnico de INTA',note:'Innovación y eficiencia para una industria competitiva.'}];return `<main class="story-page"><div class="scroll-progress" aria-hidden="true"></div><section class="story-intro wrap"><span class="eyebrow" data-reveal>FOODTEX / NOSOTROS</span><h1 data-reveal>Tecnología global.<br><span>Personas cerca.</span></h1><div class="story-intro-bottom" data-reveal><p>Conocé qué nos mueve.</p><button class="btn outline" data-action="story-jump" data-index="0">Comenzar el recorrido</button></div></section><section class="story-body wrap"><aside class="story-stage"><div class="story-visual">${chapters.map((c,i)=>`<div class="story-frame ${i===0?'active':''}" data-story-image="${i}" aria-hidden="${i!==0}">${img(c.image,c.caption,'',i!==0)}<span>${esc(c.caption)}</span></div>`).join('')}<div class="story-stage-index"><strong>01</strong><span>/ 04</span></div></div><nav class="story-nav" aria-label="Capítulos de FOODTEX">${chapters.map((c,i)=>`<button class="${i===0?'active':''}" data-action="story-jump" data-index="${i}" aria-current="${i===0?'step':'false'}"><span>${String(i+1).padStart(2,'0')}</span>${c.label}<i></i></button>`).join('')}</nav></aside><div class="story-chapters">${chapters.map((c,i)=>`<article class="story-chapter" id="story-chapter-${i}" data-story-chapter="${i}">${img(c.image,c.caption,'story-mobile-photo')}<div class="chapter-content" data-reveal><span class="chapter-number">${String(i+1).padStart(2,'0')}</span><span class="eyebrow">${c.label}</span><h2>${c.title}</h2><p>${esc(c.text)}</p><div class="chapter-note">${esc(c.note)}</div>${i===3?btn('Hablemos de tu proyecto','#/contacto'):''}</div></article>`).join('')}</div></section><section class="story-finale"><div class="wrap"><span class="eyebrow" data-reveal>TECNOLOGÍA GLOBAL. CONFIANZA LOCAL.</span><h2 data-reveal>El próximo capítulo<br><span>lo escribimos juntos.</span></h2><div data-reveal>${btn('Conocer nuestras soluciones','#/productos','light')}</div></div></section></main>`}
function news(){return `<main class="news-page final-news">${pageHero('En conexión con la industria.','Alianzas, encuentros y tecnología en planta. Historias reales de FOODTEX.','Actualidad')}<section class="section"><div class="wrap"><div class="journal-filters" aria-label="Categorías de novedades">${['Todas',...new Set(state.news.filter(n=>n.status==='Publicado').map(n=>n.category))].map(c=>`<button class="${newsCategory===c?'selected':''}" data-news-category="${esc(c)}" aria-pressed="${newsCategory===c}">${esc(c)}</button>`).join('')}</div><div id="journal-results">${journalResults()}</div></div></section></main>`}
function newsDetail(id){const n=state.news.find(n=>n.id===id&&n.status==='Publicado');if(!n)return notFound();const next=state.news.find(x=>x.status==='Publicado'&&x.id!==id);return `<main class="journal-article"><header class="article-heading wrap"><div class="breadcrumb"><a href="#/novedades">Actualidad FOODTEX</a> / ${esc(n.category)}</div><span class="eyebrow">${esc(n.category)}</span>${n.date?`<time>${esc(n.date)}</time>`:''}<h1>${esc(n.title)}</h1><p>${esc(n.summary)}</p></header><div class="article-visual wrap ${n.video?'has-film':''}">${n.video?`<video controls playsinline preload="none" poster="assets/carnave-poster.webp" aria-label="Video de puesta en marcha Marelec en Granjas Carnave"><source src="assets/${n.video}" type="video/mp4"></video><span class="article-film-label">REGISTRO REAL / GRANJAS CARNAVE S.A.</span>`:img(n.image,n.title,'',false)}</div><article class="article-reading"><span class="eyebrow">${esc(n.category)} / FOODTEX</span>${n.body.split(/\n\s*\n/).filter(Boolean).map(t=>`<p>${esc(t)}</p>`).join('')}${n.video?`<div class="case-facts"><div><span>01 / SOLUCIÓN</span><strong>Balanza compacta MARELEC</strong></div><div><span>02 / IMPLEMENTACIÓN</span><strong>Instalación y puesta en marcha</strong></div><div><span>03 / EN PLANTA</span><strong>Granjas Carnave S.A.</strong></div></div>`:''}<div class="article-conversation"><h2>¿Tenés un proyecto<br>para tu planta?</h2>${btn('Hablemos de tu proyecto','#/contacto','dark')}</div>${next?`<a class="article-next" href="#/novedad/${next.id}"><span>SEGUÍ EN CONEXIÓN / ${esc(next.category)}</span><strong>${esc(next.title)}</strong><i aria-hidden="true">↗</i></a>`:''}<a class="textlink" href="#/novedades">Ver todas las novedades</a></article></main>`}
function contactInfo(){return `<div><span class="eyebrow">Hablemos</span><h2>Estamos cerca<br>de tu industria.</h2><p>Contanos qué necesitás. Te acompañamos con asesoramiento técnico y atención personalizada.</p><div class="contact-item"><small>EMAIL</small><a href="mailto:${esc(state.settings.email)}">${esc(state.settings.email)}</a></div><div class="contact-item"><small>TELÉFONO / WHATSAPP</small><a href="https://wa.me/${digits(state.settings.phone)}" target="_blank" rel="noopener">${esc(state.settings.phone)}</a></div><div class="contact-item"><small>DIRECCIÓN</small><span>${esc(state.settings.address)}</span></div><div class="contact-item"><small>HORARIO DE ATENCIÓN</small><span>${esc(state.settings.hours)}</span></div><a style="display:inline-block;margin-top:22px" class="textlink" href="https://www.google.com/maps/search/?api=1&query=Foodtex+Concepci%C3%B3n+del+Uruguay" target="_blank" rel="noopener">Ver ubicación en Google Maps</a></div>`}
function contactForm(isQuote){return `<form id="inquiry-form" class="form-grid" novalidate><input type="hidden" name="intent" value="Consulta general"><div class="form-error-summary full" role="alert" tabindex="-1" hidden></div><div class="form-success full" role="status" hidden></div><label class="field">Nombre y apellido<input name="name" required maxlength="100" autocomplete="name" placeholder="Tu nombre"></label><label class="field">Empresa<input name="company" maxlength="100" autocomplete="organization" placeholder="Nombre de la empresa"></label><label class="field">Email<input name="email" type="email" required maxlength="150" autocomplete="email" placeholder="nombre@empresa.com"></label><label class="field">Teléfono<input name="phone" type="tel" maxlength="40" autocomplete="tel" placeholder="Código de área y número"></label><label class="field full">Ciudad y provincia<input name="city" maxlength="120" placeholder="¿Desde dónde nos contactás?"></label><label class="field full">${isQuote?'Detalles de tu solicitud':'¿Cómo podemos ayudarte?'}<textarea name="message" required maxlength="3000" placeholder="Modelo de máquina, cantidades o información que nos ayude a asesorarte..."></textarea></label><div class="full"><button type="submit" class="btn">Guardar consulta de demostración</button><p class="form-note">Esta primera versión guarda la consulta en este navegador para probar el panel. Para contactar a FOODTEX, usá WhatsApp o email.</p></div></form>`}
function contact(){return `<main class="contact-page"><section class="contact-welcome"><div class="contact-visual" aria-hidden="true"><img src="assets/conveyor-concept-v4.webp" alt="" loading="lazy"></div><div class="wrap"><span class="eyebrow">FOODTEX / CONTACTO</span><h1 class="contact-title">Hablemos<span>de lo que sigue.</span></h1><div class="contact-welcome-bottom"><p>Contanos qué necesita tu planta.<br>Te ayudamos a encontrar la solución.</p><a class="btn light" href="https://wa.me/${digits(state.settings.phone)}" target="_blank" rel="noopener">Conversar por WhatsApp</a></div></div></section><section class="section contact-section"><div class="wrap contact-grid"><div class="contact-details"><span class="eyebrow">Hablemos de tu proyecto</span><h2>Un equipo cerca de vos.</h2><p>Elegí cómo contactarnos. Para productos, equipos o soporte técnico, estamos para asesorarte.</p><a class="contact-channel" href="https://wa.me/${digits(state.settings.phone)}" target="_blank" rel="noopener"><span class="channel-symbol">W</span><span><small>WHATSAPP / TELÉFONO</small><strong>${esc(state.settings.phone)}</strong><em>Iniciá una conversación con el equipo</em></span><span class="channel-action">Abrir</span></a><a class="contact-channel" href="mailto:${esc(state.settings.email)}"><span class="channel-symbol">@</span><span><small>ESCRIBINOS</small><strong>${esc(state.settings.email)}</strong><em>Compartí los detalles de tu consulta</em></span><span class="channel-action">Email</span></a><div class="contact-location"><span class="eyebrow">Desde Entre Ríos, junto a tu industria.</span><p>${esc(state.settings.address)}</p><div class="location-bottom"><span>Atención: ${esc(state.settings.hours)}</span><a class="textlink" href="https://www.google.com/maps/search/?api=1&query=Foodtex+Concepci%C3%B3n+del+Uruguay" target="_blank" rel="noopener">Ver ubicación</a></div></div></div><div class="form-panel contact-form-card"><span class="eyebrow">Empecemos por tu necesidad</span><h3>¿Qué podemos resolver juntos?</h3><p class="contact-form-intro">Dejanos los datos y detalles de tu proyecto.</p><div class="contact-intents" role="group" aria-label="Motivo de consulta">${['Producto','Asesoramiento','Soporte'].map(x=>`<button type="button" data-contact-intent="${x}" aria-pressed="false">${x}</button>`).join('')}</div>${contactForm(false)}</div></div></section></main>`}
function quotation(){const list=quote.map(id=>state.products.find(p=>p.id===id)).filter(Boolean);return `<main class="quotation-page">${pageHero('Tu solicitud técnica.','Compartí el producto, la cantidad y los detalles de tu proceso. Nuestro equipo puede orientarte.','Cotización')}<section class="section"><div class="wrap contact-grid"><div><span class="eyebrow">PRODUCTOS SELECCIONADOS</span><h2>Del componente<br>a tu necesidad.</h2><p>${list.length?'Agregá cantidades orientativas y observaciones para preparar tu consulta.':'Podés empezar por un producto o contarnos qué necesita tu planta.'}</p>${list.map(p=>`<div class="quote-item"><div class="quote-product-head">${img(p.image,p.name)}<span><small>${esc(p.brand)}</small><strong>${esc(p.name)}</strong></span><button class="icon-btn" aria-label="Quitar ${esc(p.name)}" data-action="remove-quote" data-id="${p.id}">×</button></div><div class="quote-notes"><label class="field">Cantidad orientativa<input type="number" inputmode="numeric" min="1" max="999999" step="1" data-quote-note="quantity" data-id="${p.id}" value="${esc(quoteNotes[p.id]?.quantity||1)}"></label><label class="field">Observación<input maxlength="300" data-quote-note="note" data-id="${p.id}" placeholder="Modelo, dureza, medida..." value="${esc(quoteNotes[p.id]?.note||'')}"></label></div></div>`).join('')}<div class="actions">${btn('Explorar productos','#/productos','outline')}<a id="quote-whatsapp" class="btn" href="${quoteWhatsapp()}" target="_blank" rel="noopener">Preparar consulta por WhatsApp</a></div><p class="availability-note">Al abrir WhatsApp podés revisar y enviar el mensaje. La disponibilidad y compatibilidad se confirman con FOODTEX.</p></div><div class="form-panel contact-form-card"><span class="eyebrow">DATOS DE TU PROYECTO</span><h3>Contanos qué necesitás.</h3>${contactForm(true)}</div></div></section></main>`}
function notFound(){return `<main class="not-found"><div class="wrap"><span class="eyebrow">FOODTEX / 404</span><span class="error-number" aria-hidden="true">404</span><h1>No encontramos<br>esta página.</h1><p>Podés volver al inicio o encontrar una solución en nuestro catálogo.</p><div class="actions">${btn('Volver al inicio','#/','light')}${btn('Explorar productos','#/productos','outline')}</div></div></main>`}
function adminLayout(content,tab='dashboard'){const links=[['dashboard','▦','Resumen'],['productos','▤','Productos'],['novedades','▧','Novedades'],['consultas','✉','Consultas'],['contenido','◇','Contenido del sitio'],['vista-previa','◉','Vista previa'],['configuracion','⚙','Configuración']];return `<div class="admin-shell"><aside class="sidebar"><a href="#/admin">${img('logo-foodtex-2026-c.png','FOODTEX','logo',false)}</a><small>ADMINISTRACIÓN</small>${links.map(([id,icon,name])=>`<a class="admin-link ${tab===id?'active':''}" href="#/admin/${id}"><span>${icon}</span>${name}</a>`).join('')}<div class="sidebar-bottom"><a class="admin-link" href="#/">◉ Ver sitio web</a><a class="admin-link" href="#/admin/configuracion">⚙ Datos de la demo</a></div></aside><div class="admin-main"><div class="admin-top"><span>Panel de administración</span><div class="admin-user"><a class="textlink" href="#/">Ver sitio</a><span>Administrador</span><div class="avatar">FT</div></div></div><div class="demo-banner">Modo demostración · Cambios guardados solamente en este navegador. Sin acceso ni datos de producción.</div><main class="admin-content">${content}</main></div></div>`}
const adminHead=(title,subtitle,action='')=>`<div class="admin-head"><div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;
function productRows(list){return list.map(p=>`<tr><td><a class="cell-product" href="#/admin/producto/${p.id}">${img(p.image,p.name)}<span><strong>${esc(p.name)}</strong><small>${esc(p.brand)}</small></span></a></td><td>${esc(p.category)}</td><td><span class="badge ${p.status==='Publicado'?'':'draft'}">${p.status}</span></td><td><a class="textlink" href="#/admin/producto/${p.id}">Editar</a></td></tr>`).join('')}
const productTable=list=>`<div class="table-wrap"><table><thead><tr><th>Producto</th><th>Categoría</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${productRows(list)}</tbody></table></div>`;
function dashboard(){return adminLayout(`${adminHead('Todo bajo control.','Administrá los contenidos y las consultas de FOODTEX.',btn('Ver sitio web','#/','outline'))}<div class="stats">${[['Productos',state.products.length,`${published().length} publicados`],['Marcas',BRANDS.length,'Representadas en el sitio'],['Novedades',state.news.length,'Publicaciones disponibles'],['Consultas',state.inquiries.length,'Recibidas en esta demo']].map(([t,n,s])=>`<div class="stat"><small>${t}</small><strong>${n}</strong><div class="sub">${s}</div></div>`).join('')}</div><div class="admin-cols"><div class="panel"><div class="panel-heading"><h3>Productos del catálogo</h3><a class="textlink" href="#/admin/productos">Ver todos</a></div>${productTable(state.products.slice(0,5))}</div><div><div class="panel"><div class="panel-heading"><h3>Accesos rápidos</h3></div><div class="quick-actions"><a class="quick-action" href="#/admin/producto/nuevo">+ Crear un producto<small>Fotos, detalles y categoría</small></a><a class="quick-action" href="#/admin/novedad/nueva">+ Publicar una novedad<small>Compartí las noticias de FOODTEX</small></a><a class="quick-action" href="#/admin/contenido">◇ Editar página de inicio<small>Títulos e información institucional</small></a></div></div><div class="panel" style="margin-top:24px"><div class="panel-heading"><h3>Composición del catálogo</h3></div><div class="bars">${categories().map(c=>{const n=state.products.filter(p=>p.category===c).length;return `<div class="bar-row"><span>${esc(c)}</span><div class="bar-track"><i style="width:${n/state.products.length*100}%"></i></div><strong>${n}</strong></div>`}).join('')}</div></div></div></div><div class="admin-note">Este panel permite probar el flujo de edición. Los cambios se reflejan en el sitio de demostración y pueden restablecerse desde Configuración.</div>`)}
function adminProducts(){return adminLayout(`${adminHead('Productos','Gestioná el catálogo, las categorías y los productos destacados.',btn('+ Nuevo producto','#/admin/producto/nuevo'))}<div class="searchbar"><input type="search" id="admin-search" aria-label="Buscar en administración" placeholder="Buscar por producto o marca..." value="${esc(adminQuery)}"></div><div class="panel" id="admin-products">${productTable(state.products)}</div>`,'productos')}
const field=(label,name,value,full=false,type='text')=>`<label class="field ${full?'full':''}">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${['name','title','email'].includes(name)?'required':''} maxlength="${type==='email'?150:200}"></label>`;
function adminProduct(id){const isNew=id==='nuevo';const p=isNew?{name:'',brand:'FOODTEX',category:categories()[0],summary:'',description:'',image:'Cuchillas-Lisas-y-con-Inserto-de-Widea.jpg',features:[],specs:{},status:'Borrador',featured:false}:state.products.find(x=>x.id===id);if(!p)return adminLayout(notFound(),'productos');return adminLayout(`${adminHead(isNew?'Nuevo producto':'Editar producto','Los cambios se reflejan en el catálogo de esta demostración.',btn('Volver al catálogo','#/admin/productos','outline'))}<div class="panel"><form class="form-grid edit-form" id="product-form" data-id="${isNew?'':p.id}">${field('Nombre del producto','name',p.name,true)}${field('Marca','brand',p.brand)}<label class="field">Categoría<select name="category">${categories().map(c=>`<option ${c===p.category?'selected':''}>${esc(c)}</option>`).join('')}</select></label>${field('Descripción breve','summary',p.summary,true)}<label class="field full">Descripción técnica<textarea name="description" required maxlength="5000">${esc(p.description)}</textarea></label><label class="field full">Características (una por línea)<textarea name="features" maxlength="3000">${esc(p.features.join('\n'))}</textarea></label><label class="field full">Especificaciones (nombre: valor, una por línea)<textarea name="specs" maxlength="3000">${esc(Object.entries(p.specs).map(([k,v])=>k+': '+v).join('\n'))}</textarea></label><label class="field">Estado<select name="status"><option ${p.status==='Publicado'?'selected':''}>Publicado</option><option ${p.status==='Borrador'?'selected':''}>Borrador</option></select></label><label class="field">Destacado en inicio<select name="featured"><option value="false" ${!p.featured?'selected':''}>No</option><option value="true" ${p.featured?'selected':''}>Sí</option></select></label><div class="full">${img(p.image,p.name,'setting-logo')}<label class="field" style="margin-top:15px">Cambiar imagen<input type="file" name="photo" accept="image/png,image/jpeg,image/webp"><small style="font-size:12px;color:var(--muted)">PNG, JPG o WebP. Máximo 1 MB para esta demo.</small></label></div><div class="full actions"><button class="btn" type="submit">Guardar producto</button>${!isNew?`<button class="btn outline" type="button" data-action="delete-product" data-id="${p.id}">Eliminar producto</button>`:''}</div></form></div>`,'productos')}
function adminNews(){return adminLayout(`${adminHead('Novedades','Publicaciones institucionales, eventos y soluciones en planta.',btn('+ Nueva novedad','#/admin/novedad/nueva'))}<div class="panel"><div class="table-wrap"><table><thead><tr><th>Publicación</th><th>Categoría</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${state.news.map(n=>`<tr><td><strong style="white-space:normal;display:block;max-width:400px">${esc(n.title)}</strong></td><td>${esc(n.category)}</td><td><span class="badge ${n.status==='Publicado'?'':'draft'}">${n.status}</span></td><td><a class="textlink" href="#/admin/novedad/${n.id}">Editar</a></td></tr>`).join('')}</tbody></table></div></div>`,'novedades')}
function adminNewsEdit(id){const isNew=id==='nueva',n=isNew?{title:'',category:'Institucional',summary:'',body:'',image:'foodtex-presente-expo-avicola-2023-1.jpeg',status:'Borrador'}:state.news.find(x=>x.id===id);if(!n)return adminLayout(notFound(),'novedades');return adminLayout(`${adminHead(isNew?'Nueva novedad':'Editar novedad','Compartí noticias de FOODTEX.',btn('Volver','#/admin/novedades','outline'))}<div class="panel"><form id="news-form" class="form-grid edit-form" data-id="${isNew?'':id}">${field('Título','title',n.title,true)}${field('Categoría','category',n.category)}<label class="field">Estado<select name="status"><option ${n.status==='Publicado'?'selected':''}>Publicado</option><option ${n.status==='Borrador'?'selected':''}>Borrador</option></select></label>${field('Resumen','summary',n.summary,true)}<label class="field full">Contenido<textarea name="body" required style="min-height:230px" maxlength="8000">${esc(n.body)}</textarea></label><div class="full">${img(n.image,n.title,'setting-logo')}<label class="field">Cambiar imagen<input name="photo" type="file" accept="image/png,image/jpeg,image/webp"></label></div><div class="full actions"><button class="btn" type="submit">Guardar novedad</button>${!isNew?`<button type="button" class="btn outline" data-action="delete-news" data-id="${id}">Eliminar novedad</button>`:''}</div></form></div>`,'novedades')}
function adminInquiries(){return adminLayout(`${adminHead('Consultas','Solicitudes guardadas desde los formularios de esta demo.')}<div class="panel">${state.inquiries.length?`<div class="table-wrap"><table><thead><tr><th>Contacto</th><th>Solicitud</th><th>Fecha</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${state.inquiries.map(i=>`<tr><td><strong>${esc(i.name)}</strong><br><small>${esc(i.company||i.email)}</small></td><td>${i.products.length?'Cotización · '+i.products.length+' productos':'Consulta general'}</td><td>${new Date(i.created).toLocaleDateString('es-AR')}</td><td><span class="badge ${i.status==='Nueva'?'draft':''}">${i.status}</span></td><td><button class="btn ghost" data-action="view-inquiry" data-id="${i.id}">Ver consulta</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h3>No hay consultas todavía.</h3><p>Probá el formulario del sitio y la solicitud aparecerá acá.</p>'+btn('Probar formulario','#/contacto','outline')+'</div>'}</div>`,'consultas')}
function contentEdit(){const s=state.settings;return adminLayout(`${adminHead('Contenido del sitio','Editá la portada y la información institucional.')}<div class="panel"><form class="form-grid edit-form" id="content-form">${field('Título principal de inicio','title',s.title,true)}<label class="field full">Texto de la portada<textarea name="subtitle" maxlength="600" required>${esc(s.subtitle)}</textarea></label><label class="field full">Quiénes somos<textarea name="about" maxlength="2500" required>${esc(s.about)}</textarea></label><label class="field full">Misión<textarea name="mission" maxlength="1500" required>${esc(s.mission)}</textarea></label><label class="field full">Visión<textarea name="vision" maxlength="1500" required>${esc(s.vision)}</textarea></label><div class="full"><button class="btn">Guardar contenidos</button></div></form></div>`,'contenido')}
function settings(){const s=state.settings;return adminLayout(`${adminHead('Configuración','Datos de contacto y herramientas de la demostración.')}<div class="panel"><form class="form-grid edit-form" id="settings-form">${field('Email de contacto','email',s.email,false,'email')}${field('Teléfono / WhatsApp','phone',s.phone)}${field('Dirección','address',s.address,true)}${field('Horario de atención','hours',s.hours,true)}<div class="full"><button class="btn">Guardar configuración</button></div></form></div><div class="panel" style="margin-top:25px"><div class="panel-heading"><h3>Datos de la demostración</h3></div><div style="padding:25px"><p style="margin-top:0">Exportá los contenidos editados o volvé al contenido inicial recuperado del sitio FOODTEX.</p><div class="actions"><button class="btn outline" data-action="export">Exportar contenidos · JSON</button><button class="btn outline" data-action="reset">Restablecer demostración</button></div></div></div>`,'configuracion')}
function render(){window.foodtexExplorerCleanup?.();window.foodtexPreviewCleanup?.();const r=route();dialog.close();document.title=(r.startsWith('/admin')?'Administración':'FOODTEX')+' · Reliable Solutions';if(r.startsWith('/admin')){const parts=r.split('/');app.innerHTML=parts[2]==='producto'?adminProduct(parts[3]):parts[2]==='novedad'?adminNewsEdit(parts[3]):({productos:adminProducts,novedades:adminNews,consultas:adminInquiries,contenido:contentEdit,configuracion:settings,'vista-previa':previewPage}[parts[2]]||dashboard)();}else{let content=r==='/'?home():r==='/productos'?catalogue():r==='/nosotros'?about():r==='/novedades'?news():r==='/contacto'?contact():r==='/cotizacion'?quotation():r.startsWith('/producto/')?productDetail(r.split('/')[2]):r.startsWith('/novedad/')?newsDetail(r.split('/')[2]):notFound();app.innerHTML=header()+content+footer();if(r==='/productos')filterProducts();}document.body.classList.toggle('home-route',r==='/');window.scrollTo({top:0,left:0,behavior:'instant'});initMotion();initPreview();initExplorer();updatePageMeta(r)}
function addQuote(id){if(!published().some(p=>p.id===id))throw Error('Producto no disponible');if(!quote.includes(id)){quote.push(id);localStorage.setItem('foodtex-quote-v1',JSON.stringify(quote));toast('Producto agregado a tu cotización.')}else toast('Este producto ya está en tu cotización.');const y=window.scrollY;render();window.scrollTo({top:y,left:0,behavior:'instant'});return {products:quote.length}}
function confirmDialog(title,message,action){dialog.innerHTML=`<button class="icon-btn close" data-action="close-dialog" aria-label="Cerrar">×</button><h2>${title}</h2><p>${message}</p><div class="actions" style="margin-top:25px"><button class="btn" id="confirm-action">Confirmar</button><button class="btn outline" data-action="close-dialog">Cancelar</button></div>`;dialog.showModal();document.querySelector('#confirm-action').onclick=()=>{action();dialog.close()}}
async function uploadedImage(form,fallback){const file=form.querySelector('[name=photo]')?.files[0];if(!file)return fallback;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>1048576)throw Error('Elegí una imagen PNG, JPG o WebP de hasta 1 MB.');return new Promise((res,rej)=>{const reader=new FileReader;reader.onload=()=>res(reader.result);reader.onerror=()=>rej(Error('No se pudo leer la imagen.'));reader.readAsDataURL(file)})}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const {action,id}=el.dataset;if(action==='scroll-tour'){e.preventDefault();document.querySelector('#recorrido')?.scrollIntoView({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}if(action==='story-jump'){e.preventDefault();document.querySelector('#story-chapter-'+el.dataset.index)?.scrollIntoView({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})}if(action==='menu'){const nav=document.querySelector('.navlinks');nav.classList.toggle('open');el.setAttribute('aria-expanded',nav.classList.contains('open'))}if(action==='add-quote')addQuote(id);if(action==='request-quote'){addQuote(id);location.hash='/cotizacion';}if(action==='remove-quote'){quote=quote.filter(x=>x!==id);localStorage.setItem('foodtex-quote-v1',JSON.stringify(quote));render()}if(action==='filter'){category=el.dataset.category;const y=window.scrollY;render();window.scrollTo({top:y,left:0,behavior:'instant'})}if(action==='clear-filters'){category='Todos';query='';render()}if(action==='close-dialog')dialog.close();if(action==='delete-product')confirmDialog('Eliminar producto','El producto se eliminará del catálogo de esta demostración.',()=>{state.products=state.products.filter(p=>p.id!==id);quote=quote.filter(x=>x!==id);localStorage.setItem('foodtex-quote-v1',JSON.stringify(quote));save();location.hash='/admin/productos';toast('Producto eliminado.')});if(action==='delete-news')confirmDialog('Eliminar novedad','La publicación se eliminará de esta demostración.',()=>{state.news=state.news.filter(n=>n.id!==id);save();location.hash='/admin/novedades';toast('Novedad eliminada.')});if(action==='reset')confirmDialog('Restablecer demostración','Se borrarán los cambios y las consultas locales, y se restaurará el contenido inicial.',()=>{state=clone(SEED);quote=[];quoteNotes={};save();localStorage.removeItem('foodtex-quote-v1');localStorage.removeItem('foodtex-quote-notes-v1');render();toast('Demostración restablecida.')});if(action==='export'){const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='foodtex-contenidos-demo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}if(action==='view-inquiry'){const i=state.inquiries.find(x=>x.id===id);dialog.innerHTML=`<button class="icon-btn close" data-action="close-dialog" aria-label="Cerrar">×</button><h2>${esc(i.name)}</h2><p>${esc(i.company)}<br>${esc(i.email)}<br>${esc(i.phone)} · ${esc(i.city)}</p><h4>Consulta</h4><p style="white-space:pre-wrap">${esc(i.message)}</p>${i.products.length?'<h4>Productos</h4><ul>'+i.products.map(p=>'<li>'+esc(p)+'</li>').join('')+'</ul>':''}<button class="btn" data-action="review-inquiry" data-id="${id}">Marcar como revisada</button>`;dialog.showModal()}if(action==='review-inquiry'){state.inquiries.find(i=>i.id===id).status='Revisada';save();render();toast('Consulta marcada como revisada.')}});
document.addEventListener('input',e=>{if(e.target.id==='product-search'){query=e.target.value;filterProducts()}if(e.target.id==='admin-search'){adminQuery=e.target.value;document.querySelector('#admin-products').innerHTML=productTable(state.products.filter(p=>(p.name+' '+p.brand).toLowerCase().includes(adminQuery.toLowerCase())))}});
document.addEventListener('submit',async e=>{const form=e.target;if(!['product-form','news-form','content-form','settings-form','inquiry-form'].includes(form.id))return;e.preventDefault();const f=Object.fromEntries(new FormData(form));try{if(form.id==='product-form'){const existing=state.products.find(p=>p.id===form.dataset.id);const image=await uploadedImage(form,existing?.image||'Cuchillas-Lisas-y-con-Inserto-de-Widea.jpg');const p={...existing,id:existing?.id||crypto.randomUUID(),name:f.name.trim(),brand:f.brand.trim(),category:f.category,summary:f.summary.trim(),description:f.description.trim(),features:f.features.split('\n').map(t=>t.trim()).filter(Boolean),specs:Object.fromEntries(f.specs.split('\n').filter(t=>t.includes(':')).map(t=>{const at=t.indexOf(':');return [t.slice(0,at).trim(),t.slice(at+1).trim()]})),status:f.status,featured:f.featured==='true',image};if(existing)state.products[state.products.indexOf(existing)]=p;else state.products.push(p);if(save()){location.hash='/admin/productos';toast('Producto guardado.')}}if(form.id==='news-form'){const existing=state.news.find(n=>n.id===form.dataset.id);const image=await uploadedImage(form,existing?.image||'foodtex-presente-expo-avicola-2023-1.jpeg');const n={...existing,id:existing?.id||crypto.randomUUID(),title:f.title.trim(),category:f.category.trim(),summary:f.summary.trim(),body:f.body.trim(),status:f.status,image};if(existing)state.news[state.news.indexOf(existing)]=n;else state.news.unshift(n);if(save()){location.hash='/admin/novedades';toast('Novedad guardada.')}}if(form.id==='content-form'||form.id==='settings-form'){for(const [key,value] of Object.entries(f))state.settings[key]=value.trim();if(save())toast('Cambios guardados. Ya se reflejan en el sitio.')}if(form.id==='inquiry-form'){state.inquiries.unshift({...f,id:crypto.randomUUID(),created:new Date().toISOString(),status:'Nueva',products:route()==='/cotizacion'?quote.map(id=>{const p=state.products.find(p=>p.id===id),n=quoteNotes[id];return p?`${p.name} · cantidad: ${n?.quantity||1}${n?.note?' · '+n.note:''}`:null}).filter(Boolean):[]});if(save()){form.reset();document.querySelectorAll('[data-contact-intent]').forEach(b=>b.setAttribute('aria-pressed','false'));const success=form.querySelector('.form-success');if(success){success.hidden=false;success.textContent='Consulta de demostración guardada en este navegador. Podés verla en Administración. Para contactar al equipo, usá WhatsApp o email.';}toast('Consulta de demostración guardada. Podés verla en Administración.')}}}catch(error){toast(error.message)}});
window.addEventListener('hashchange',render);render();
if(document.modelContext?.registerTool){try{const lifecycle=new AbortController;window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});for(const tool of [{name:'foodtex_search_products',description:'Busca productos publicados del catálogo FOODTEX.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(typeof input.query!=='string')throw Error('query debe ser texto');return published().filter(p=>(p.name+' '+p.brand).toLowerCase().includes(input.query.toLowerCase())).map(p=>({id:p.id,name:p.name,brand:p.brand}))}},{name:'foodtex_add_to_quotation',description:'Agrega un producto publicado a la selección local de cotización. No envía una consulta.',inputSchema:{type:'object',properties:{productId:{type:'string'}},required:['productId'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(typeof input.productId!=='string')throw Error('productId debe ser texto');return addQuote(input.productId)}}])Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}

function initMotion(){
 window.foodtexMotionCleanup?.();
 const root=document.querySelector('main');
 if(!root||!window.matchMedia)return;
 const media=window.matchMedia('(prefers-reduced-motion: reduce)'),reduce=media.matches;
 let observer=null,frame=0;
 if(!reduce&&typeof IntersectionObserver!=='undefined'){root.classList.add('motion-ready');observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in-view');observer.unobserve(e.target)}}),{threshold:.08,rootMargin:'0px 0px -20px 0px'});document.querySelectorAll('[data-reveal],.footer-wordmark').forEach(el=>observer.observe(el));}
 const progress=root.querySelector('.scroll-progress'),parallax=[...root.querySelectorAll('[data-parallax]')],chapters=[...root.querySelectorAll('[data-story-chapter]')],images=[...root.querySelectorAll('[data-story-image]')],nav=[...root.querySelectorAll('.story-nav button')],index=root.querySelector('.story-stage-index strong'),wordBlock=root.querySelector('.word-scroll');
 if(wordBlock&&!wordBlock.dataset.prepared){const words=wordBlock.textContent.trim().split(/\s+/);wordBlock.replaceChildren(...words.map((word,i)=>{const span=document.createElement('span');span.textContent=word+(i<words.length-1?' ':'');return span}));wordBlock.dataset.prepared='true';}
 const words=wordBlock?[...wordBlock.children]:[];const headerEl=document.querySelector('.header'),serviceRows=[...root.querySelectorAll('[data-service-step]')],serviceFrames=[...root.querySelectorAll('[data-service-frame]')],serviceNumber=root.querySelector('.service-display-number'),serviceLine=root.querySelector('.service-line-fill');let manualUntil=0;
 function activateService(i){root.querySelector('.service-machine')?.setAttribute('data-active',String(i));serviceRows.forEach((n,k)=>{n.classList.toggle('active',k===i);n.querySelector('button')?.setAttribute('aria-pressed',String(k===i))});serviceFrames.forEach((n,k)=>{n.classList.toggle('active',k===i);n.setAttribute('aria-hidden',String(k!==i))});if(serviceNumber)serviceNumber.textContent=String(i+1).padStart(2,'0');if(serviceLine)serviceLine.style.transform=`scaleY(${(i+1)/serviceRows.length})`;}
 function serviceInteraction(e){const row=e.target.closest('[data-service-step]');if(row){manualUntil=Date.now()+1600;activateService(Number(row.dataset.serviceStep));}}
 root.addEventListener('click',serviceInteraction);root.addEventListener('focusin',serviceInteraction);root.addEventListener('pointerover',serviceInteraction);
 function update(){frame=0;const footerMark=document.querySelector('.footer-wordmark');if(footerMark&&footerMark.getBoundingClientRect().top<window.innerHeight-20)footerMark.classList.add('in-view');root.querySelectorAll('.manifesto,.immersive-section,.statement-section').forEach(n=>{const r=n.getBoundingClientRect();if(!reduce&&window.innerWidth>760&&r.bottom>0&&r.top<window.innerHeight)n.style.setProperty('--scene-progress',Math.max(0,Math.min(1,(window.innerHeight-r.top)/(window.innerHeight+r.height))));});headerEl?.classList.toggle('scrolled',window.scrollY>35);const h=window.innerHeight,y=window.scrollY,max=document.documentElement.scrollHeight-h;if(progress)progress.style.transform=`scaleX(${max>0?Math.min(1,y/max):0})`;
 if(!reduce&&window.innerWidth>760){parallax.forEach(n=>{const r=n.getBoundingClientRect();if(r.bottom>-150&&r.top<h+150)n.style.transform=`translate3d(0,${Math.max(-30,Math.min(30,(h/2-r.top-r.height/2)*Number(n.dataset.parallax)))}px,0)`});if(wordBlock){const r=wordBlock.getBoundingClientRect(),p=Math.max(0,Math.min(1,(h*.82-r.top)/(h*.48+r.height)));words.forEach((word,i)=>word.classList.toggle('lit',p>i/words.length));}}
 if(serviceRows.length&&Date.now()>manualUntil){let selected=0,nearest=Infinity;serviceRows.forEach((n,i)=>{const r=n.getBoundingClientRect(),d=Math.abs(r.top+r.height/2-h*.55);if(d<nearest){nearest=d;selected=i}});activateService(selected);}
 if(chapters.length){let active=0,distance=Infinity;chapters.forEach((chapter,i)=>{const r=chapter.getBoundingClientRect(),d=Math.abs(r.top+r.height*.3-h*.42);if(d<distance){distance=d;active=i}});images.forEach((im,i)=>{im.classList.toggle('active',i===active);im.setAttribute('aria-hidden',String(i!==active));});nav.forEach((b,i)=>{b.classList.toggle('active',i===active);b.setAttribute('aria-current',i===active?'step':'false')});if(index)index.textContent=String(active+1).padStart(2,'0');}
 }
 function onScroll(){if(!frame)frame=requestAnimationFrame(update)}
 function onPointer(e){if(reduce||e.pointerType==='touch')return;const card=e.target.closest('.product-card');if(card){const r=card.getBoundingClientRect();card.style.setProperty('--mx',((e.clientX-r.left)/r.width*100)+'%');card.style.setProperty('--my',((e.clientY-r.top)/r.height*100)+'%');}}
 window.addEventListener('scroll',onScroll,{passive:true});window.addEventListener('resize',onScroll,{passive:true});root.addEventListener('pointermove',onPointer,{passive:true});
 function cleanup(){observer?.disconnect();root.removeEventListener('click',serviceInteraction);root.removeEventListener('focusin',serviceInteraction);root.removeEventListener('pointerover',serviceInteraction);window.removeEventListener('scroll',onScroll);window.removeEventListener('resize',onScroll);root.removeEventListener('pointermove',onPointer);media.removeEventListener?.('change',onChange);if(frame)cancelAnimationFrame(frame);root.classList.remove('motion-ready');parallax.forEach(n=>n.style.transform='');}
 function onChange(){initMotion()}
 media.addEventListener?.('change',onChange,{once:true});window.foodtexMotionCleanup=cleanup;update();
}

function previewPage(){return adminLayout(`${adminHead('Vista previa','Recorré el sitio en distintos tamaños antes de presentarlo.')}<div class="preview-toolbar"><label class="field">Pantalla<select id="preview-width">${[320,360,375,390,430,768,1024,1280,1366,1440,1600,1920].map(w=>`<option value="${w}" ${w===390?'selected':''}>${w}px · ${w<500?'Móvil':w<1100?'Tablet':'Escritorio'}</option>`).join('')}</select></label><label class="field">Página<select id="preview-route">${[['/','Inicio'],['/productos','Productos'],['/nosotros','Nosotros'],['/novedades','Novedades'],['/contacto','Contacto'],['/cotizacion','Cotización'],['/producto/cuchillas','Ficha de producto'],['/novedad/marelec','Caso / artículo'],['/pagina-no-disponible','404']].map(([r,t])=>`<option value="${r}">${t}</option>`).join('')}</select></label><p>Podés navegar y desplazarte dentro de la vista.</p></div><div class="preview-canvas"><div class="preview-stage"><iframe class="preview-frame" title="Vista previa responsive de FOODTEX" src="./#/" width="390" height="720"></iframe></div></div>`,'vista-previa')}
function initPreview(){const frame=document.querySelector('.preview-frame');if(!frame)return;const size=document.querySelector('#preview-width'),page=document.querySelector('#preview-route'),stage=document.querySelector('.preview-stage'),canvas=document.querySelector('.preview-canvas');function fit(){const width=Number(size.value),scale=Math.min(1,(canvas.clientWidth-24)/width);frame.style.width=width+'px';frame.style.height='720px';frame.style.transform=`scale(${scale})`;stage.style.width=width*scale+'px';stage.style.height=720*scale+'px';}function navigate(){frame.src='./#'+page.value;}size.addEventListener('change',fit);page.addEventListener('change',navigate);const observer=new ResizeObserver(fit);observer.observe(canvas);fit();window.foodtexPreviewCleanup=()=>{observer.disconnect();size.removeEventListener('change',fit);page.removeEventListener('change',navigate);};}

function initExplorer(){
 const section=document.querySelector('.solutions-explorer'),stage=section?.querySelector('.explorer-stage'),cards=stage?[...stage.querySelectorAll('.explorer-card')]:[],tabs=section?[...section.querySelectorAll('[data-explore]')]:[],film=document.querySelector('.carnave-film'),video=film?.querySelector('video');
 if(!section&&!film)return;
 const mobile=window.matchMedia('(max-width:760px)'),reduced=window.matchMedia('(prefers-reduced-motion:reduce)');let active=0,drag=null,raf=0,suppressClick=false;
 const disposers=[];function listen(n,event,fn,opts){if(n){n.addEventListener(event,fn,opts);disposers.push(()=>n.removeEventListener(event,fn,opts));}}
 function activate(i){active=Math.max(0,Math.min(cards.length-1,i));cards.forEach((card,k)=>{const on=k===active;card.classList.toggle('active',on);card.toggleAttribute('inert',!mobile.matches&&!on);card.setAttribute('aria-hidden',String(!mobile.matches&&!on));card.setAttribute('role',mobile.matches?'article':'tabpanel');if(mobile.matches)card.removeAttribute('aria-labelledby');else card.setAttribute('aria-labelledby','solution-tab-'+k);});tabs.forEach((tab,k)=>{tab.setAttribute('aria-selected',String(k===active));tab.tabIndex=k===active?0:-1;});const label=section?.querySelector('.explorer-progress b'),bar=section?.querySelector('.explorer-progress i');if(label)label.textContent=String(active+1).padStart(2,'0');if(bar)bar.style.transform=`scaleX(${(active+1)/cards.length})`;}
 tabs.forEach((tab,i)=>{listen(tab,'pointerenter',e=>{if(e.pointerType==='mouse'&&!drag)activate(i)});listen(tab,'click',()=>activate(i));listen(tab,'focus',()=>activate(i));listen(tab,'keydown',e=>{let next=e.key==='ArrowDown'||e.key==='ArrowRight'?active+1:e.key==='ArrowUp'||e.key==='ArrowLeft'?active-1:e.key==='Home'?0:e.key==='End'?cards.length-1:null;if(next!==null){e.preventDefault();activate((next+cards.length)%cards.length);tabs[active].focus();}});});
 listen(stage,'scroll',()=>{if(mobile.matches&&!raf)raf=requestAnimationFrame(()=>{raf=0;const x=stage.scrollLeft;let i=0,d=Infinity;cards.forEach((c,k)=>{const distance=Math.abs(c.offsetLeft-stage.offsetLeft-x);if(distance<d){d=distance;i=k;}});activate(i);});},{passive:true});
 listen(stage,'pointerdown',e=>{if(mobile.matches||e.button!==0||e.target.closest('a,button'))return;drag={x:e.clientX,i:active,id:e.pointerId};stage.setPointerCapture(e.pointerId);stage.classList.add('dragging');});
 listen(stage,'pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.x;if(Math.abs(dx)>55){activate(drag.i+(dx<0?1:-1));suppressClick=true;}});
 function release(){drag=null;stage?.classList.remove('dragging');setTimeout(()=>suppressClick=false,0);}listen(stage,'pointerup',release);listen(stage,'pointercancel',release);listen(stage,'click',e=>{if(suppressClick){e.preventDefault();e.stopPropagation();}},true);
 function reset(){activate(active);if(mobile.matches&&stage)stage.scrollLeft=cards[active].offsetLeft-stage.offsetLeft;stopVideo();}listen(mobile,'change',reset);
 function stopVideo(){if(video){video.pause();video.classList.remove('playing');}}
 function playVideo(){if(!video||mobile.matches||reduced.matches||navigator.connection?.saveData)return;if(!video.getAttribute('src'))video.src=window.innerWidth<=1024?'assets/carnave-preview-mobile.mp4':'assets/carnave-preview.mp4';video.play().then(()=>video.classList.add('playing')).catch(()=>stopVideo());}
 listen(film,'pointerenter',e=>{if(e.pointerType==='mouse')playVideo();});listen(film,'pointerleave',stopVideo);listen(film,'focusin',playVideo);listen(film,'focusout',stopVideo);listen(reduced,'change',stopVideo);listen(document,'visibilitychange',()=>{if(document.hidden)stopVideo();});
 let visibility=null;if(film&&typeof IntersectionObserver!=='undefined'){visibility=new IntersectionObserver(es=>{if(!es[0].isIntersecting)stopVideo();});visibility.observe(film);}
 activate(0);window.foodtexExplorerCleanup=()=>{disposers.forEach(f=>f());visibility?.disconnect();stopVideo();if(raf)cancelAnimationFrame(raf);};
}

function institutionalScene(){return `<section class="institutional-scene section"><div class="wrap"><div class="institutional-title"><span class="eyebrow" data-reveal>PERSONAS DETRÁS DE LAS SOLUCIONES</span><h2><span data-reveal>Tecnología global.</span><span data-reveal>Cercanía local.</span></h2></div><figure class="institutional-photo" data-reveal>${img('foodtex-presente-expo-avicola-2023-1.jpeg','FOODTEX en Expo Avícola 2023')}<figcaption>FOODTEX / EXPO AVÍCOLA 2023</figcaption></figure><div class="institutional-bottom"><p>${esc(state.settings.about)}</p><a class="textlink" href="#/nosotros">Conocer FOODTEX <span aria-hidden="true">↗</span></a></div><div class="institutional-statements">${[['01','Tecnología','Insumos y equipos de marcas líderes.'],['02','Implementación','Instalación y soporte técnico especializado.'],['03','Cercanía','Asesoramiento y atención personalizada.']].map(x=>`<div data-reveal><span>${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p></div>`).join('')}</div></div></section>`;}
function journalSelection(){const all=state.news.filter(n=>n.status==='Publicado');const feature=all.find(n=>n.id==='expo2023')||all[0];return {feature,others:all.filter(n=>n!==feature)};}
function journalLead(n){return `<article class="journal-lead"><a class="journal-image" href="#/novedad/${n.id}">${img(n.image,n.title)}</a><div><span class="eyebrow">${esc(n.category)}</span><h3><a href="#/novedad/${n.id}">${esc(n.title)}</a></h3><p>${esc(n.summary)}</p><a class="textlink" href="#/novedad/${n.id}">Leer novedad <span aria-hidden="true">↗</span></a></div></article>`;}
function journalSide(n){return `<article class="journal-side"><a href="#/novedad/${n.id}"><span class="eyebrow">${esc(n.category)}</span><h3>${esc(n.title)}</h3>${img(n.image,n.title)}<span class="journal-side-action">LEER NOVEDAD <i aria-hidden="true">↗</i></span></a></article>`;}
function journalHome(){const {feature,others}=journalSelection();if(!feature)return '';return `<section class="brand-journal section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">ACTUALIDAD FOODTEX</span><h2>En conexión<br>con la industria.</h2></div>${btn('Todas las novedades','#/novedades','outline')}</div><div class="journal-layout">${journalLead(feature)}<div class="journal-sidebar">${others.slice(0,2).map(journalSide).join('')}</div></div></div></section>`;}
function journalResults(){const list=state.news.filter(n=>n.status==='Publicado'&&(newsCategory==='Todas'||n.category===newsCategory));if(!list.length)return `<div class="empty"><h2>No hay novedades en esta categoría.</h2><button class="btn outline" data-news-category="Todas">Ver todas</button></div>`;const feature=list.find(n=>n.id==='expo2023')||list[0];return `<div class="journal-layout">${journalLead(feature)}<div class="journal-sidebar">${list.filter(n=>n!==feature).slice(0,2).map(journalSide).join('')}</div></div><div class="journal-archive">${list.filter(n=>n!==feature).slice(2).map(journalSide).join('')}</div>`;}
function quoteWhatsapp(){const names=quote.map(id=>{const p=state.products.find(x=>x.id===id),n=quoteNotes[id];return p?`${p.name} (cantidad orientativa: ${n?.quantity||1})${n?.note?' — '+n.note:''}`:null;}).filter(Boolean);return `https://wa.me/${digits(state.settings.phone)}?text=${encodeURIComponent('Hola FOODTEX, quisiera asesoramiento y cotización para: '+(names.join('; ')||'mi proyecto')+'.')}`;}
function updatePageMeta(r){const p=r.startsWith('/producto/')?published().find(x=>x.id===r.split('/')[2]):null,n=r.startsWith('/novedad/')?state.news.find(x=>x.id===r.split('/')[2]):null;const title=p?.name||n?.title||({'/':'Insumos y tecnología para la industria frigorífica','/productos':'Productos y soluciones industriales','/nosotros':'Tecnología global. Personas cerca.','/novedades':'Actualidad FOODTEX','/contacto':'Contacto','/cotizacion':'Solicitud técnica'}[r]);document.title=(r.startsWith('/admin')?'Administración':title||'Página no encontrada')+' · FOODTEX';document.querySelector('meta[name="description"]')?.setAttribute('content',p?.summary||n?.summary||(r==='/contacto'?'Contactá a FOODTEX para productos, asesoramiento, instalación y soporte técnico.':'FOODTEX: insumos, equipos y soporte técnico para la industria frigorífica. Tecnología global, cercanía local.'));}
document.addEventListener('click',e=>{const newsButton=e.target.closest('[data-news-category]');if(newsButton){newsCategory=newsButton.dataset.newsCategory;document.querySelector('#journal-results').innerHTML=journalResults();document.querySelectorAll('.journal-filters button').forEach(b=>{const active=b.dataset.newsCategory===newsCategory;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active));});}const intent=e.target.closest('[data-contact-intent]');if(intent){document.querySelectorAll('[data-contact-intent]').forEach(b=>b.setAttribute('aria-pressed',String(b===intent)));document.querySelector('#inquiry-form [name="intent"]').value=intent.dataset.contactIntent;}const menu=e.target.closest('[data-action="menu"]');if(menu&&menu.getAttribute('aria-expanded')==='true')document.querySelector('.navlinks a')?.focus();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const menu=document.querySelector('.menu');if(menu?.getAttribute('aria-expanded')==='true'){document.querySelector('.navlinks')?.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.focus();}}});
document.addEventListener('input',e=>{const field=e.target.closest('[data-quote-note]');if(field){const id=field.dataset.id;quoteNotes[id]??={quantity:1,note:''};quoteNotes[id][field.dataset.quoteNote]=field.dataset.quoteNote==='quantity'?Math.max(1,Math.min(999999,Math.floor(Number(field.value)||1))):field.value.slice(0,300);try{localStorage.setItem('foodtex-quote-notes-v1',JSON.stringify(quoteNotes));}catch{toast('No se pudo guardar la observación en este navegador.');}document.querySelector('#quote-whatsapp')?.setAttribute('href',quoteWhatsapp());}if(e.target.closest('#inquiry-form')&&e.target.matches('input,textarea')){e.target.removeAttribute('aria-invalid');e.target.removeAttribute('aria-describedby');e.target.parentElement.querySelector('.field-error')?.remove();}});
document.addEventListener('submit',e=>{const form=e.target;if(form.id!=='inquiry-form')return;form.querySelectorAll('.field-error').forEach(n=>n.remove());const invalid=[...form.querySelectorAll('input:not([type=hidden]),textarea')].filter(n=>!n.checkValidity()||(n.required&&!n.value.trim()));const summary=form.querySelector('.form-error-summary');if(invalid.length){e.preventDefault();e.stopImmediatePropagation();summary.hidden=false;summary.textContent='Revisá los campos indicados antes de guardar tu consulta.';invalid.forEach(n=>{n.setAttribute('aria-invalid','true');const error=document.createElement('span');error.className='field-error';error.id='error-'+n.name;error.textContent=n.validity.typeMismatch?'Ingresá un email válido.':'Completá este campo con un valor válido.';n.setAttribute('aria-describedby',error.id);n.parentElement.append(error);});invalid[0].focus();}else{summary.hidden=true;form.querySelectorAll('[aria-invalid]').forEach(n=>n.removeAttribute('aria-invalid'));}},true);
